import asyncio,json,pathlib,shutil
from playwright.async_api import async_playwright
R=pathlib.Path(__file__).resolve().parent.parent
fixture=json.loads((R/'verification-3.6/ui-fixture.json').read_text())
fixture['settings'].update(crossChatMemory=True,visionEndpoint='http://127.0.0.1:1234/v1',visionModel='local-vision-test',ffmpegPath='C:\\tools\\ffmpeg.exe',banditPath='C:\\tools\\bandit.exe')
