fixture['current']['messages'][0]['text']='Сообщение пользователя';a=fixture['current']['messages'][-1];a.update(text='Оченьдлинноеслово'*90+'\n\n```python\n'+('x'*1200)+'\n```',connectionOffer='cloudflare',connectionDismissed=False,rating=0)
checks=[]
def check(v,n):
 assert v,n
 checks.append(n)
async def run():
 async with async_playwright() as p:
  b=await p.chromium.launch(executable_path=shutil.which('chromium'),headless=True,args=['--no-sandbox'])
  page=await b.new_page(viewport={'width':1440,'height':940});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
  await page.add_init_script('window.__sent=[];window.chrome={webview:{postMessage(x){__sent.push(JSON.parse(x))},addEventListener(){}}}')
  await page.goto((R/'src/ui.html').as_uri());await page.evaluate('(d)=>receive({type:"state",data:d})',fixture)
  user=page.locator('.msg.user');assistant=page.locator('.msg.assistant')
  check(await user.locator('.message-actions button').count()==1,'user has Copy only, no Edit')
  await page.mouse.move(1,1);check(await user.locator('.message-actions').evaluate('e=>getComputedStyle(e).opacity')=='0','user actions hidden off-hover')
  await user.hover();check(await user.locator('.message-actions').evaluate('e=>getComputedStyle(e).opacity')=='1','user Copy appears on hover')
  check(await assistant.locator('.message-actions button').count()==3,'assistant persistent Copy/Like/Dislike')
  await page.mouse.move(1,1);check(await assistant.locator('.message-actions').is_visible(),'assistant actions visible without hover')
  await assistant.get_by_role('button',name='👍 Нравится').click();check(await page.evaluate('__sent.at(-1).action==="feedback"&&__sent.at(-1).data.rating===1'),'Like dispatch')
  await assistant.get_by_role('button',name='👎 Не нравится').click();await page.locator('#feedback-note').fill('Не хватает тестов');await page.locator('#feedback-save').click();check(await page.evaluate('__sent.at(-1).data.note==="Не хватает тестов"&&__sent.at(-1).data.rating===-1'),'Dislike optional reason dispatch; no generation')
  await assistant.locator('.connection-offer .primary').click();check(await page.evaluate('__sent.at(-1).action==="connectorCard"&&__sent.at(-1).data.id==="cloudflare"'),'natural connection offer uses actual server id')
  await assistant.locator('.connection-offer button').filter(has_text='Позже').click();check(await page.evaluate('__sent.at(-1).action==="connectorLater"'),'Later dismissal dispatch')
  # simulate native browser taking half the window; UI gets its own 560px viewport
  await page.set_viewport_size({'width':560,'height':900});await page.evaluate('receive({type:"browserSplit",data:true})')
  check(await page.evaluate('document.documentElement.scrollWidth===innerWidth'),'split viewport document has no horizontal overflow')
  check(await page.locator('.thread').evaluate('e=>e.scrollWidth<=e.clientWidth+1'),'long answer stays inside chat pane')
  check(await assistant.locator('pre').evaluate('e=>e.scrollWidth>e.clientWidth'),'long code scrolls only within its own block')
  await page.screenshot(path=str(R/'verification-3.8/chat-split.png'))
  await page.locator('#mcp-btn').evaluate('e=>e.click()');await page.locator('[data-connection-tab="connected"]').click();check(await page.locator('#mcp-list .card').count()==1,'Connected tab filters disconnected services')
  await page.locator('[data-connection-tab="manage"]').click();check(await page.locator('#connections-manage').is_visible() and await page.locator('#mcp-list').is_hidden(),'Manage tab separates custom URL/import controls')
  await page.locator('[data-connection-tab="browse"]').click();await page.locator('#registry-query').fill('cloudflare');await page.locator('#registry-search').click();check(await page.evaluate('__sent.at(-1).action==="registrySearch"&&__sent.at(-1).data.cursor===""'),'live registry query dispatch')
  await page.evaluate('receive({type:"registryResults",data:{entries:[{id:"com.cloudflare/mcp",name:"Cloudflare <script>",description:"Test fixture, not connected",version:"1",url:"https://mcp.cloudflare.com/mcp",source:"https://developers.cloudflare.com"}],cursor:"page2"}})')
  check(await page.locator('#registry-results strong').inner_text()=='Cloudflare <script>','registry untrusted labels rendered as text')
  await page.locator('#registry-next').click();check(await page.evaluate('__sent.at(-1).data.cursor==="page2"'),'registry pagination dispatch')
  await page.locator('#registry-results button').click();check(await page.evaluate('__sent.at(-1).action==="registryAdd"&&__sent.at(-1).data.id==="com.cloudflare/mcp"'),'registry add requires separate host confirmation')
  modal=page.locator('#mcp-modal .modal');await modal.evaluate('e=>e.scrollTop=0');box=await modal.bounding_box();await page.mouse.move(box['x']+20,box['y']+200);await page.mouse.wheel(0,900);await page.wait_for_timeout(400);check(await modal.evaluate('e=>e.scrollTop>100'),'connections modal real wheel scroll')
  await page.screenshot(path=str(R/'verification-3.8/connections.png'))
  await page.evaluate('closeModal();settingsModal()');check(await page.locator('#s-vision-model').input_value()=='local-vision-test','vision settings loaded')
  await page.locator('#settings-form button[type=submit]').click();check(await page.evaluate('__sent.at(-1).data.ffmpegPath==="C:\\\\tools\\\\ffmpeg.exe"') if False else await page.evaluate('__sent.at(-1).data.visionModel==="local-vision-test"&&__sent.at(-1).data.ffmpegPath.length>0'),'vision and utility settings preserved on save')
  await page.evaluate('receive({type:"utilityPath",data:{kind:"ffmpeg",path:"C:/new/ffmpeg.exe"}})');check(await page.locator('#s-ffmpeg').input_value()=='C:/new/ffmpeg.exe','utility picker updates correct field')
  await page.evaluate('closeModal()');await page.locator('#memory-btn').evaluate('e=>e.click()');check(await page.locator('#cross-chat-memory').is_checked(),'cross-chat search visible and enabled')
  await page.locator('#cross-chat-memory').uncheck();check(await page.evaluate('__sent.at(-1).action==="crossChatMemory"&&__sent.at(-1).data.enabled===false'),'cross-chat privacy toggle dispatch')
  await page.evaluate('closeModal()');await page.set_viewport_size({'width':390,'height':844});check(await page.evaluate('document.documentElement.scrollWidth===innerWidth'),'mobile no horizontal overflow')
  # Real DOM execution of C#-generated scripts, not string matching.
  dom=await b.new_page(viewport={'width':800,'height':600});await dom.set_content('''<h1>Page title</h1><p id="hidden" style="display:none">HIDDEN SECRET TEXT</p><input aria-label="Search" value="PRIVATE_INPUT_VALUE"><button onclick="window.clicked=true">Go</button><input type="password" aria-label="Password" value="SECRET_PASSWORD"><textarea>SECRET_TEXTAREA</textarea><div contenteditable="true">SECRET_EDITABLE</div><iframe></iframe>''')
  script=(R/'src/browser-dom.js').read_text().replace('__NORA_NONCE__','"123abc"');snap=await dom.evaluate(script)
  check('PRIVATE_INPUT_VALUE' not in json.dumps(snap) and 'SECRET_PASSWORD' not in json.dumps(snap) and 'SECRET_TEXTAREA' not in json.dumps(snap) and 'SECRET_EDITABLE' not in json.dumps(snap),'snapshot never reads input/textarea/contenteditable values')
  check('HIDDEN SECRET TEXT' not in snap['text'],'snapshot excludes hidden fallback text')
  check(snap['iframeCount']==1 and len(snap['elements'])>=3,'numbered DOM controls and iframe limitation')
  actions=json.loads((R/'verification-3.8/action-scripts.json').read_text());await dom.evaluate(actions['type']);check(await dom.locator('input').first.input_value()=="a'b\"\\n",'actual browser typing handles quotes/backslash and digit nonce')
  await dom.evaluate(actions['click']);check(await dom.evaluate('window.clicked===true'),'actual browser button click')
  await dom.locator('input').first.evaluate('e=>e.type="password"')
  try:await dom.evaluate(actions['type']);raise AssertionError('sensitive dynamic field not rejected')
  except Exception as e:check('Защищённое' in str(e),'dynamic secret-field mutation rechecked at action time')
  await dom.close();check(not errors,'no UI JavaScript exceptions');await b.close()
 (R/'verification-3.8/ui-results.json').write_text(json.dumps({'passed':len(checks),'checks':checks},ensure_ascii=False,indent=2));print(str(len(checks))+' Update38 UI/DOM checks passed')
asyncio.run(run())
